@meta.ShaderSource('flatten.wgsl')
const String source = r'''

// import "storage/uniforms.wgsl"
const NONE = 0xffffffffu;

struct World {
  world_to_screen: mat4x4f,
  viewport: vec2f,
  tolerance: f32,
}

struct StorageCounts {
  draw: u32,
  draw_edge: u32,
}

struct StorageOffsets {
  geometry_frame: u32,
  geometry_frame_inverse: u32,
  geometry_vertex: u32,
  geometry_covertex: u32,
  geometry_edge: u32,
  
  topology_vertex: u32,
  topology_edge: u32,
  topology_face: u32,
  topology_covertex: u32,
  topology_face_boundary: u32,

  style_vertex: u32,
  style_edge: u32,
  style_face: u32,

  glyph_data: u32,
  glyph_boundary: u32,
  glyph_geometry: u32,

  draw_entry: u32,
  draw_edge: u32,
  draw_order: u32,
}

struct StorageCapacity {
  segments: u32,
}
// end import "storage/uniforms.wgsl"

// import "storage/topology.wgsl"
// import "../_bindings.wgsl"
// end import "../_bindings.wgsl"


struct VertexTopology {
  disk_start: u32,
  parent: u32,
}

struct EdgeTopology {
  vertex_start: u32,
  vertex_end: u32,
  parent: u32,
}

struct FaceTopology {
  boundary_span: vec2u,
  parent: u32,
}

struct CovertexTopology {
  edge: u32,
  is_start: u32,
  next: u32,
}

struct FaceBoundaryEntry {
  edge: u32,
  is_forward: u32,
}

fn read_vertex_topology(index: u32) -> VertexTopology {
  let offset = storage_offsets.topology_vertex + index * 2u;
  return VertexTopology(
    bitcast<u32>(topology[offset + 0u]),
    bitcast<u32>(topology[offset + 1u])
  );
}

fn read_edge_topology(index: u32) -> EdgeTopology {
  let offset = storage_offsets.topology_edge + index * 3u;
  return EdgeTopology(
    bitcast<u32>(topology[offset + 0u]),
    bitcast<u32>(topology[offset + 1u]),
    bitcast<u32>(topology[offset + 2u])
  );
}

fn read_face_topology(index: u32) -> FaceTopology {
  let offset = storage_offsets.topology_face + index * 3u;
  return FaceTopology(
    vec2u(
      bitcast<u32>(topology[offset + 0u]),
      bitcast<u32>(topology[offset + 1u]),
    ),
    bitcast<u32>(topology[offset + 2u])
  );
}

fn read_covertex_topology(index: u32) -> CovertexTopology {
  let offset = storage_offsets.topology_covertex + index * 3u;
  return CovertexTopology(
    bitcast<u32>(topology[offset + 0u]),
    bitcast<u32>(topology[offset + 1u]),
    bitcast<u32>(topology[offset + 2u])
  );
}

fn read_face_boundary_entry(index: u32) -> FaceBoundaryEntry {
  let offset = storage_offsets.topology_face_boundary + index * 2u;
  return FaceBoundaryEntry(
    bitcast<u32>(topology[offset + 0u]),
    bitcast<u32>(topology[offset + 1u])
  );
}
// end import "storage/topology.wgsl"

// import "storage/geometry.wgsl"
// import "../math/cubic.wgsl"
// import "math.wgsl"
const PI = 3.141592653589793;

// import "arc.wgsl"
fn count_arc_segments(angle: f32, r: f32, tolerance: f32, max_segments: u32) -> u32 {
  let x = tolerance / r;

  var step: f32;
  if (x >= 2.0) {
    step = 2.0 * PI;
  }
  else if (x > 1e-3) {
    step = 2.0 * acos(1.0 - x);
  }
  else {
    step = 2.0 * sqrt(2.0 * x);
  }

  return clamp(u32(ceil(angle / step)), 1u, max_segments);
}
// end import "arc.wgsl"

// import "quadratic.wgsl"
struct Quadratic2 {
  p0: vec2f,
  p1: vec2f,
  p2: vec2f,
}

fn quadratic2_bbox(c: Quadratic2) -> vec4f {
  var lo = min(c.p0, min(c.p1, c.p2));
  var hi = max(c.p0, max(c.p1, c.p2));
  return vec4f(lo, hi);
}

fn quadratic2_transform(q: Quadratic2, m: mat4x4f) -> Quadratic2 {
  return Quadratic2(
    (m * vec4f(q.p0, 0.0, 1.0)).xy,
    (m * vec4f(q.p1, 0.0, 1.0)).xy,
    (m * vec4f(q.p2, 0.0, 1.0)).xy,
  );
}

fn quadratic2_wang(q: Quadratic2, tolerance: f32) -> f32 {
  let chord = q.p2 - q.p0;
  let chord_len2 = dot(chord, chord);
  let d = q.p1 - q.p0;
  let c = vec2_cross(d, chord);
  if (c * c <= 4.0 * tolerance * tolerance * chord_len2) {
    let pr = dot(d, chord);
    if (pr >= 0.0 && pr <= chord_len2) { return 1.0; }
  }

  let v = q.p2 - 2.0 * q.p1 + q.p0;
  let m = dot(v, v);
  if (m < 1.0e-6) { return 1.0; }
  return max(1.0, sqrt(sqrt(m) * 3.0 / (4.0 * tolerance)));
}
// end import "quadratic.wgsl"

// import "vector.wgsl"
fn vec2_cross(a: vec2f, b: vec2f) -> f32 {
  return a.x * b.y - a.y * b.x;
}

fn vec2_orthogonal(v: vec2f) -> vec2f {
  return vec2f(-v.y, v.x);
}

fn vec2_safe_tangent(tan: vec2f, fallback: vec2f) -> vec2f {
  return select(normalize(tan), normalize(fallback), dot(tan, tan) < 1e-9);
}

fn vec2_transform(m: mat4x4f, v: vec2f) -> vec2f {
  return (m * vec4f(v, 0.0, 1.0)).xy;
}

const BBOX_INV_INF = vec4f(1e30, 1e30, -1e30, -1e30);

fn bbox_hull_point(bbox: vec4f, p: vec2f) -> vec4f {
  return vec4f(
    min(bbox.xy, p),
    max(bbox.zw, p)
  );
}

fn bbox_hull_bbox(bbox: vec4f, other: vec4f) -> vec4f {
  return vec4f(
    min(bbox.xy, other.xy),
    max(bbox.zw, other.zw)
  );
}

fn bbox_inflate(bbox: vec4f, dx: f32, dy: f32) -> vec4f {
  return vec4f(
    bbox.x - dx,
    bbox.y - dy,
    bbox.z + dx,
    bbox.w + dy
  );
}

fn bbox_size(bbox: vec4f) -> vec2f {
  return bbox.zw - bbox.xy;
}
// end import "vector.wgsl"

// import "matrix.wgsl"
fn mat4_translate2(t: vec2f) -> mat4x4f {
  return mat4x4f(
    vec4f(1.0, 0.0, 0.0, 0.0),
    vec4f(0.0, 1.0, 0.0, 0.0),
    vec4f(0.0, 0.0, 1.0, 0.0),
    vec4f(t, 0.0, 1.0)
  );
}

fn mat4_scale2(s: vec2f) -> mat4x4f {
  return mat4x4f(
    vec4f(s.x, 0.0, 0.0, 0.0),
    vec4f(0.0, s.y, 0.0, 0.0),
    vec4f(0.0, 0.0, 1.0, 0.0),
    vec4f(0.0, 0.0, 0.0, 1.0)
  );
}

fn mat4_translate2_scale2(t: vec2f, s: vec2f) -> mat4x4f {
  return mat4x4f(
    vec4f(s.x, 0.0, 0.0, 0.0),
    vec4f(0.0, s.y, 0.0, 0.0),
    vec4f(0.0, 0.0, 1.0, 0.0),
    vec4f(t, 0.0, 1.0)
  );
}
// end import "matrix.wgsl"
// end import "math.wgsl"


struct Cubic2 { p0: vec2f, p1: vec2f, p2: vec2f, p3: vec2f }

fn cubic2_reversed(c: Cubic2) -> Cubic2 {
  return Cubic2(c.p3, c.p2, c.p1, c.p0);
}

fn cubic2_transform(c: Cubic2, m: mat4x4f) -> Cubic2 {
  return Cubic2(
    (m * vec4f(c.p0, 0.0, 1.0)).xy,
    (m * vec4f(c.p1, 0.0, 1.0)).xy,
    (m * vec4f(c.p2, 0.0, 1.0)).xy,
    (m * vec4f(c.p3, 0.0, 1.0)).xy
  );
}

// Evaluates the cubic bezier at parameter [t].
fn cubic2_pos(c: Cubic2, t: f32) -> vec2f {
  let mt = 1.0 - t;
  let mt2 = mt * mt;
  let t2 = t * t;

  return c.p0 * (mt2 * mt) + c.p1 * (3.0 * mt2 * t) + c.p2 * (3.0 * mt * t2) + c.p3 * (t2 * t);
}

// Evaluates the tangent of the cubic bezier at parameter [t].
fn cubic2_tan(c: Cubic2, t: f32) -> vec2f {
  let mt = 1.0 - t;
  let mt2 = mt * mt;
  let t2 = t * t;
  return (c.p1 - c.p0) * (3.0 * mt2) + (c.p2 - c.p1) * (6.0 * mt * t) + (c.p3 - c.p2) * (3.0 * t2);
}

// Evaluates the acceleration of the cubic bezier at parameter [t].
fn cubic2_acc(c: Cubic2, t: f32) -> vec2f {
  let mt = 1.0 - t;
  return (c.p2 - 2.0 * c.p1 + c.p0) * (6.0 * mt) + (c.p3 - 2.0 * c.p2 + c.p1) * (6.0 * t);
}

// Evaluates the position and the tangent of the cubic bezier at parameter [t].
fn cubic2_pos_tan(c: Cubic2, t: f32) -> vec4f {
  let mt = 1.0 - t;
  let mt2 = mt * mt;
  let t2 = t * t;

  let pos = c.p0 * (mt2 * mt) + c.p1 * (3.0 * mt2 * t) + c.p2 * (3.0 * mt * t2) + c.p3 * (t2 * t);
  let tan = (c.p1 - c.p0) * (3.0 * mt2) + (c.p2 - c.p1) * (6.0 * mt * t) + (c.p3 - c.p2) * (3.0 * t2);
  return vec4f(pos, tan);
}

// Returns the number of line segments needed to approximate the cubic bezier within the given tolerance.
fn cubic2_wang(c: Cubic2, tolerance: f32) -> f32 {
  let chord = c.p3 - c.p0;
  let chord_len2 = dot(chord, chord);
  let d1 = c.p1 - c.p0;
  let d2 = c.p2 - c.p0;
  let c1 = vec2_cross(d1, chord);
  let c2 = vec2_cross(d2, chord);
  let max_cross2 = max(c1 * c1, c2 * c2);
  if (9.0 * max_cross2 <= 16.0 * tolerance * tolerance * chord_len2) {
    let pr1 = dot(d1, chord);
    let pr2 = dot(d2, chord);
    if (pr1 >= 0.0 && pr1 <= chord_len2 && pr2 >= 0.0 && pr2 <= chord_len2) { return 1.0; }
  }

  let v1 = c.p2 - 2.0 * c.p1 + c.p0;
  let v2 = c.p3 - 2.0 * c.p2 + c.p1;
  let m = max(dot(v1, v1), dot(v2, v2));
  if (m < 1.0e-6) { return 1.0; }
  return max(1.0, sqrt(sqrt(m) * 3.0 / (4.0 * tolerance)));
}

// Splits the cubic bezier at [t].
fn cubic2_split_at(c: Cubic2, t: f32) -> array<Cubic2, 2> {
  let p01 = mix(c.p0, c.p1, t);
  let p12 = mix(c.p1, c.p2, t);
  let p23 = mix(c.p2, c.p3, t);

  let p012 = mix(p01, p12, t);
  let p123 = mix(p12, p23, t);

  let p0123 = mix(p012, p123, t);

  return array<Cubic2, 2>(
    Cubic2(c.p0, p01, p012, p0123),
    Cubic2(p0123, p123, p23, c.p3)
  );
}

// Returns the cubic bezier piece between [t0] and [t1].
fn cubic2_piece_at(c: Cubic2, t0: f32, t1: f32) -> Cubic2 {
  let pos_tan_t0 = cubic2_pos_tan(c, t0);
  let pos_tan_t1 = cubic2_pos_tan(c, t1);
  let dt = (t1 - t0) / 3.0;

  return Cubic2(
    pos_tan_t0.xy,
    pos_tan_t0.xy + pos_tan_t0.zw * dt,
    pos_tan_t1.xy - pos_tan_t1.zw * dt,
    pos_tan_t1.xy
  );
}

fn cubic2_bbox(c: Cubic2) -> vec4f {
  var lo = min(c.p0, min(c.p1, min(c.p2, c.p3)));
  var hi = max(c.p0, max(c.p1, max(c.p2, c.p3)));
  return vec4f(lo, hi);
}
// end import "../math/cubic.wgsl"


fn read_frame_transform(index: u32) -> mat4x4f {
  let offset = storage_offsets.geometry_frame + index * 16u;
  return mat4x4f(
    bitcast<f32>(geometry[offset + 0u]),
