  );
}
// end import "storage/geometry.wgsl"

// import "storage/draw.wgsl"
struct DrawEntry {
  cell: u32,
  kind: u32,
  decoration_span: vec2u,
}

const DRAW_ENTRY_KIND_VERTEX = 1u;
const DRAW_ENTRY_KIND_EDGE = 2u;
const DRAW_ENTRY_KIND_FACE_FAN = 3u;
const DRAW_ENTRY_KIND_FACE_COVER = 4u;
const DRAW_ENTRY_KIND_GLYPH_EDGE = 5u;
const DRAW_ENTRY_KIND_GLYPH_FACE_FAN = 6u;
const DRAW_ENTRY_KIND_GLYPH_FACE_COVER = 7u;

fn read_draw_entry(index: u32) -> DrawEntry {
  let offset = storage_offsets.draw_entry + index * 4u;
  return DrawEntry(
    bitcast<u32>(draw[offset + 0u]),
    bitcast<u32>(draw[offset + 1u]),
    vec2u(bitcast<u32>(draw[offset + 2u]), bitcast<u32>(draw[offset + 3u]))
  );
}

fn read_draw_edge(index: u32) -> u32 {
  let offset = storage_offsets.draw_edge + index;
  return bitcast<u32>(draw[offset]);
}

fn read_draw_order(index: u32) -> u32 {
  let offset = storage_offsets.draw_order + index;
  return bitcast<u32>(draw[offset]);
}
// end import "storage/draw.wgsl"


// import "utils/limits.wgsl"
const MAX_CUBIC_SEGMENT_COUNT: u32 = 128;
const MAX_QUADRATIC_SEGMENT_COUNT: u32 = 64;
const MAX_ARC_SEGMENTS: u32 = 128;
const MAX_VERTEX_VALENCE = 8u;
// end import "utils/limits.wgsl"

// import "utils/world_utils.wgsl"
fn read_vertex_position_world(index: u32) -> vec2f {
  let local_position = read_vertex_position(index);
  let parent = read_vertex_topology(index).parent;
  let transform = read_frame_transform(parent);
  return (transform * vec4f(local_position, 0.0, 1.0)).xy;
}

fn read_covertex_tangent_world(vertex_index: u32, covertex_index: u32) -> vec2f {
  let local_tangent = read_covertex_tangent(covertex_index);
  let parent = read_vertex_topology(vertex_index).parent;
  let transform = read_frame_transform(parent);
  return (transform * vec4f(local_tangent, 0.0, 0.0)).xy;
}

fn read_edge_cubic_world(index: u32) -> Cubic2 {
  let local_cubic = read_edge_cubic(index);
  let parent = read_edge_topology(index).parent;
  let transform = read_frame_transform(parent);
  return cubic2_transform(local_cubic, transform);
}

